const date=()=>new Date().toLocaleDateString('ms-MY');
function id(prefix=''){let u=new Uint8Array(12);crypto.getRandomValues(u);return prefix+Array.from(u).map(x=>x.toString(16).padStart(2,'0')).join('')}
function saveF(){try{localStorage.setItem(FAMILY_KEY,JSON.stringify(F));return true}catch(ex){msg(L('Storan keluarga tidak tersedia.','Family storage unavailable.'));return false}}
function saveT(){try{localStorage.setItem(TEACHER_KEY,JSON.stringify(T));return true}catch(ex){msg(L('Storan guru tidak tersedia atau penuh.','Teacher storage unavailable or full.'));return false}}
