// Teacher cryptographic keys are non-extractable and kept in IndexedDB (same origin).
function dbOpen(){return new Promise((resolve,reject)=>{let r=indexedDB.open('wm-monitor-r3-keys',1);r.onupgradeneeded=()=>r.result.createObjectStore('keys');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function keyGet(){const db=await dbOpen();return new Promise((res,rej)=>{let tx=db.transaction('keys','readonly'),req=tx.objectStore('keys').get('teacher');req.onsuccess=()=>{db.close();res(req.result)};req.onerror=()=>{db.close();rej(req.error)}})}
async function keyPut(value){const db=await dbOpen();return new Promise((res,rej)=>{let tx=db.transaction('keys','readwrite');tx.objectStore('keys').put(value,'teacher');tx.oncomplete=()=>{db.close();res()};tx.onerror=()=>{db.close();rej(tx.error)}})}
async function keys(){if(!crypto?.subtle||!indexedDB)throw Error('Web Crypto atau IndexedDB tidak tersedia.');let k=await keyGet();if(k)return k;
 let pair=await crypto.subtle.generateKey({name:'RSA-OAEP',modulusLength:2048,publicExponent:new Uint8Array([1,0,1]),hash:'SHA-256'},false,['encrypt','decrypt']);let jwk=await crypto.subtle.exportKey('jwk',pair.publicKey);
 k={publicKey:pair.publicKey,privateKey:pair.privateKey,publicJwk:jwk};await keyPut(k);return k}
const b64=x=>{let arr=new Uint8Array(x),out='';for(let i=0;i<arr.length;i+=16384)out+=String.fromCharCode(...arr.slice(i,i+16384));return btoa(out)};
const bytes=x=>Uint8Array.from(atob(x),c=>c.charCodeAt(0));
async function encryptReport(payload){const k=await keys(),aes=await crypto.subtle.generateKey({name:'AES-GCM',length:256},true,['encrypt','decrypt']),iv=crypto.getRandomValues(new Uint8Array(12)),plain=new TextEncoder().encode(JSON.stringify(payload));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},aes,plain),raw=await crypto.subtle.exportKey('raw',aes),wrapped=await crypto.subtle.encrypt({name:'RSA-OAEP'},k.publicKey,raw);
 return {format:'WM-R3-WMR-ENCRYPTED-DEMO',version:1,exportId:id('ex_'),createdAt:new Date().toISOString(),wrappedKey:b64(wrapped),iv:b64(iv),ciphertext:b64(cipher)} }
async function decryptReport(obj){if(!obj||obj.format!=='WM-R3-WMR-ENCRYPTED-DEMO'||obj.version!==1||!obj.wrappedKey||!obj.iv||!obj.ciphertext)throw Error('Format laporan tidak sah');const k=await keys(),raw=await crypto.subtle.decrypt({name:'RSA-OAEP'},k.privateKey,bytes(obj.wrappedKey));const aes=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['decrypt']),dec=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(obj.iv)},aes,bytes(obj.ciphertext));return JSON.parse(new TextDecoder().decode(dec))}
function download(obj,file){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=file;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000)}
async function send(demo){let p=active();if(!p?.studentId)return msg('Pautkan profil dengan kelas terlebih dahulu.');if(!document.getElementById('wmmConsent').checked)return msg('Sila semak persetujuan penjaga dahulu.');let status=document.getElementById('wmmParentState');status.textContent='🔒 Menyulitkan laporan...';try{let last=events(p),payload={schema:'WM-MONITOR-R4',schemaVersion:'wm.monitor.report.v1',profileId:p.id,studentId:p.studentId,classId:p.classId,year:p.year,alias:p.alias,events:last.slice(-200).map(ev=>r4Event(ev,p.id)),sentAt:new Date().toISOString()},file=await encryptReport(payload);
 if(demo){let box=load(DEMO_BOX,()=>({items:[]}));box.items=Array.isArray(box.items)?box.items:[];box.items.push(file);if(box.items.length>250)box.items=box.items.slice(-250);try{localStorage.setItem(DEMO_BOX,JSON.stringify(box));status.textContent='✓ Laporan tersulit tiba dalam peti demo peranti ini. Buka Ruang Cikgu untuk import.'}catch(x){status.textContent='Storan peti demo penuh. Cuba muat turun fail .wmr.'}}
 else {download(file,'WM_RPT_'+file.exportId.slice(-10).toUpperCase()+'.wmr');status.textContent='✓ Fail .wmr berjaya disediakan (bukan upload cloud).'}
 }catch(ex){status.textContent='Gagal: '+ex.message}}
function showTeacherTabs(){return `<div class="wmm-tabs"><button class="wmm-tab ${teacherTab==='overview'?'active':''}" data-tt="overview">📊 ${L('Ringkasan','Overview')}</button><button class="wmm-tab ${teacherTab==='class'?'active':''}" data-tt="class">🏫 ${L('Kelas & Kod','Classes & codes')}</button><button class="wmm-tab ${teacherTab==='inbox'?'active':''}" data-tt="inbox">📥 ${L('Peti Laporan','Report Inbox')}</button><button class="wmm-tab ${teacherTab==='reward'?'active':''}" data-tt="reward">🏆 ${L('Ganjaran','Rewards')}</button></div>`}
